-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird der $eq-Operator in MongoDB verwendet, um nach exakt übereinstimmenden Werten zu suchen?', 2, '[{"text": "Ja", "correct": true, "because": "$eq prüft auf Gleichheit"}, {"text": "Nein", "correct": false, "because": "Definition von $eq"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der $gt-Operator in MongoDB Werte finden, die kleiner als ein angegebener Wert sind?', 2, '[{"text": "Nein", "correct": true, "because": "$gt bedeutet größer als"}, {"text": "Ja", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der $lt-Operator in MongoDB dazu geeignet, Werte zu finden, die kleiner als ein bestimmter Wert sind?', 2, '[{"text": "Ja", "correct": true, "because": "$lt bedeutet kleiner als"}, {"text": "Nein", "correct": false, "because": "Definition von $lt"}]'),
('00000000-0000-0000-0000-000000000000', 'Erlaubt der $in-Operator in MongoDB die Suche nach Werten, die in einer Liste enthalten sind?', 2, '[{"text": "Ja", "correct": true, "because": "$in prüft auf Listenzugehörigkeit"}, {"text": "Nein", "correct": false, "because": "Zweck von $in"}]'),
('00000000-0000-0000-0000-000000000000', 'Kombiniert der $and-Operator in MongoDB mehrere Bedingungen, die alle erfüllt sein müssen?', 2, '[{"text": "Ja", "correct": true, "because": "$and verlangt alle Bedingungen"}, {"text": "Nein", "correct": false, "because": "Definition von $and"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Query-Operator in MongoDB sucht nach exakter Übereinstimmung eines Wertes?', 2, '[{"text": "$eq", "correct": true, "because": "Gleichheit prüfen"}, {"text": "$gt", "correct": false, "because": "Größer als"}, {"text": "$lt", "correct": false, "because": "Kleiner als"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator wird verwendet, um Werte zu finden, die größer als ein angegebener Wert sind?', 3, '[{"text": "$gt", "correct": true, "because": "Größer als"}, {"text": "$eq", "correct": false, "because": "Gleichheit"}, {"text": "$in", "correct": false, "because": "Listensuche"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Query-Operator sucht nach Werten, die kleiner als ein bestimmter Wert sind?', 2, '[{"text": "$lt", "correct": true, "because": "Kleiner als"}, {"text": "$gt", "correct": false, "because": "Größer als"}, {"text": "$and", "correct": false, "because": "Kombination"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator erlaubt die Suche nach Werten, die in einer vorgegebenen Liste enthalten sind?', 2, '[{"text": "$in", "correct": true, "because": "Listenzugehörigkeit"}, {"text": "$eq", "correct": false, "because": "Exakte Übereinstimmung"}, {"text": "$lt", "correct": false, "because": "Kleiner als"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator kombiniert mehrere Bedingungen in einer MongoDB-Abfrage?', 2, '[{"text": "$and", "correct": true, "because": "Logisches UND"}, {"text": "$in", "correct": false, "because": "Listensuche"}, {"text": "$gt", "correct": false, "because": "Größer als"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Query-Operatoren gibt es in MongoDB?', 4, '[{"text": "$eq", "correct": true, "because": "Gleichheit"}, {"text": "$gt", "correct": true, "because": "Größer als"}, {"text": "$lt", "correct": true, "because": "Kleiner als"}, {"text": "$sum", "correct": false, "because": "Aggregationsoperator"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat der $in-Operator in MongoDB?', 3, '[{"text": "Sucht in einer Liste", "correct": true, "because": "Listenzugehörigkeit"}, {"text": "Effizient für mehrere Werte", "correct": true, "because": "Vereinfacht Abfragen"}, {"text": "Kann Arrays abfragen", "correct": true, "because": "Unterstützt Array-Suchen"}, {"text": "Kombiniert Bedingungen", "correct": false, "because": "$and"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren dienen Vergleichszwecken in MongoDB?', 4, '[{"text": "$eq", "correct": true, "because": "Gleichheit"}, {"text": "$gt", "correct": true, "because": "Größer als"}, {"text": "$lt", "correct": true, "because": "Kleiner als"}, {"text": "$and", "correct": false, "because": "Logische Kombination"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen kann der $and-Operator in MongoDB erfüllen?', 3, '[{"text": "Kombiniert mehrere Bedingungen", "correct": true, "because": "Logisches UND"}, {"text": "Erfordert alle Bedingungen erfüllt", "correct": true, "because": "Alle müssen wahr sein"}, {"text": "Kann mit anderen Operatoren genutzt werden", "correct": true, "because": "Flexibel kombinierbar"}, {"text": "Sucht in Listen", "correct": false, "because": "$in"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren sind für numerische Vergleiche in MongoDB geeignet?', 3, '[{"text": "$gt", "correct": true, "because": "Größer als"}, {"text": "$lt", "correct": true, "because": "Kleiner als"}, {"text": "$eq", "correct": true, "because": "Gleichheit"}, {"text": "$in", "correct": false, "because": "Listensuche"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) $eq sucht nach exakten Übereinstimmungen. b) Es findet Werte größer als ein Schwellenwert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gleichheit ja, größer nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) $gt sucht Werte größer als ein angegebener Wert. b) $lt sucht Werte größer als ein Schwellenwert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größer ja, kleiner nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) $in sucht Werte in einer Liste. b) Es kombiniert mehrere Bedingungen logisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Liste ja, Kombination nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) $and erfordert, dass alle Bedingungen wahr sind. b) $eq sucht nur numerische Werte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle wahr ja, $eq flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) $lt findet Werte kleiner als ein Schwellenwert. b) $in ist für numerische Vergleiche gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kleiner ja, Liste nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

